export function reduceTaskBacklogEvent(event) {
    if (event.type !== "TASK_BACKLOG_EVALUATED")
        return [];
    const { pendingCount } = event.payload;
    if (pendingCount < 0)
        return [];
    if (pendingCount === 0) {
        return [{
                type: "CLEANUP_TASK_BACKLOG_LOOPS",
                entityType: "task",
                payload: { pendingCount },
            }];
    }
    return [];
}
